    // Immutable mapping: preserve longest-match precedence without sorting per row.
    private val longestBrandMatches: List<Pair<(String) -> Boolean, Int>> =
        brandMappings.entries.sortedByDescending { it.key.length }.map { (key, resId) -> matcher(key) to resId }

    /** Short Latin keys ("x", "qq") must stand alone, or "Exxon" would get the X logo. */
    private fun matcher(key: String): (String) -> Boolean {
        if (key.length > 3 || key.any { it.code > 0x7F }) return { name -> name.contains(key) }
        val word = Regex("(?<![a-z0-9])${Regex.escape(key)}(?![a-z0-9])")
        return { name -> word.containsMatchIn(name) }
    }

    fun getIconResource(merchantName: String): Int? {
        InstitutionCatalog.find(merchantName)?.let { return it.iconResId }
        val normalized = merchantName.lowercase()
        return longestBrandMatches.firstOrNull { (matches, _) -> matches(normalized) }?.second
    }
    
